describe('Clear All Filters Functionality', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-testid="search-page"]').should('be.visible');
  });

  it('should clear all applied filters when clicking the clear all button', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="price-range-100-500"]').click();

    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="brand-option-samsung"]').click();

    // Verify filters are applied
    cy.get('[data-testid="active-filter-electronics"]').should('be.visible');
    cy.get('[data-testid="active-filter-price-100-500"]').should('be.visible');
    cy.get('[data-testid="active-filter-samsung"]').should('be.visible');

    // Verify search results are filtered
    cy.get('[data-testid="search-results"]').children().should('have.length.greaterThan', 0);
    cy.get('[data-testid="search-results"]').children().first().should('contain', 'Samsung');

    // Click clear all filters button
    cy.get('[data-testid="clear-all-filters-btn"]').click();

    // Verify all filters are removed
    cy.get('[data-testid="active-filter-electronics"]').should('not.exist');
    cy.get('[data-testid="active-filter-price-100-500"]').should('not.exist');
    cy.get('[data-testid="active-filter-samsung"]').should('not.exist');

    // Verify filter inputs are reset
    cy.get('[data-testid="filter-category"]').should('not.be.checked');
    cy.get('[data-testid="price-range-100-500"]').should('not.be.checked');
    cy.get('[data-testid="brand-option-samsung"]').should('not.be.checked');

    // Verify all results are displayed
    cy.get('[data-testid="search-results"]').children().should('have.length.greaterThan', 3);
  });

  it('should disable clear all button when no filters are applied', () => {
    // Verify clear all button is disabled initially
    cy.get('[data-testid="clear-all-filters-btn"]').should('be.disabled');
    cy.get('[data-testid="clear-all-filters-btn"]').should('have.attr', 'aria-disabled', 'true');

    // Apply a single filter
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    // Verify clear all button is enabled
    cy.get('[data-testid="clear-all-filters-btn"]').should('not.be.disabled');
    cy.get('[data-testid="clear-all-filters-btn"]').should('have.attr', 'aria-disabled', 'false');

    // Clear filters
    cy.get('[data-testid="clear-all-filters-btn"]').click();

    // Verify button is disabled again
    cy.get('[data-testid="clear-all-filters-btn"]').should('be.disabled');
  });

  it('should maintain URL state consistency after clearing filters', () => {
    // Apply filters and verify URL contains filter parameters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    cy.url().should('include', 'category=electronics');

    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="price-range-100-500"]').click();

    cy.url().should('include', 'price=100-500');

    // Clear all filters
    cy.get('[data-testid="clear-all-filters-btn"]').click();

    // Verify URL is clean without filter parameters
    cy.url().should('not.include', 'category=');
    cy.url().should('not.include', 'price=');
  });

  it('should show confirmation message after clearing filters', () => {
    // Apply filters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="brand-option-apple"]').click();

    // Clear filters
    cy.get('[data-testid="clear-all-filters-btn"]').click();

    // Verify success message appears
    cy.get('[data-testid="filter-cleared-message"]').should('be.visible');
    cy.get('[data-testid="filter-cleared-message"]').should('contain', 'All filters cleared');

    // Verify message disappears after timeout
    cy.get('[data-testid="filter-cleared-message"]').should('not.be.visible', { timeout: 5000 });
  });

  it('should handle clearing filters with search query present', () => {
    // Enter search query
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Apply filters
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-option-electronics"]').click();

    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="price-range-500-1000"]').click();

    // Verify search query is still present
    cy.get('[data-testid="search-input"]').should('have.value', 'laptop');

    // Clear filters
    cy.get('[data-testid="clear-all-filters-btn"]').click();

    // Verify filters are cleared but search query remains
    cy.get('[data-testid="active-filter-electronics"]').should('not.exist');
    cy.get('[data-testid="active-filter-price-500-1000"]').should('not.exist');
    cy.get('[data-testid="search-input"]').should('have.value', 'laptop');

    // Verify results still contain search term
    cy.get('[data-testid="search-results"]').children().first().should('contain', 'laptop');
  });
});
